    def sub_slices(self, chunk_size=16) -> Generator[Tuple[Tuple[int, int], Tuple[slice, slice, slice], SubSelectionBox], None, None]:
        for (cx, cz), box in self.sub_sections(chunk_size):
            slices = box.chunk_slice(cx, cz, chunk_size)
