            physical_operation.update({
                "id": self.name,
                "type": "physical",
                "name": self.name,
                "mac_address": str(self.iface.mac_address),
            })
            if addrs:
                physical_operation["subnets"] = addrs
        elif version == 2:
            physical_operation.update({
                "match": {
                    "macaddress": str(self.iface.mac_address),
                },
                # Unclear what we want, so just let it be the default.
