        for (obj, name), ty in tc.attribute_tyenv.items():
            if (obj, name) in self.attribute_tyenv.keys():
                self.attribute_tyenv[(obj, name)] = \
                        join(ty, self.attribute_tyenv[(obj, name)])
            else:
                self.attribute_tyenv[(obj, name)] = ty

        unify(ty_ret, TyNone())
        return TyNone()


