        q_biorbd = GeneralizedCoordinates(q)
        qdot_biorbd = GeneralizedVelocity(qdot)
        torque_max, torque_min = self.model.torqueMax(q_biorbd, qdot_biorbd)
        return torque_max.to_mx(), torque_min.to_mx()

