        elif scope == SC_GLOBAL:
            if not self.optimized:
                self.emitop(prefix + '_NAME', name)
            else:
                self.emitop(prefix + '_GLOBAL', name)
        elif scope == SC_FREE or scope == SC_CELL:
            self.emitop(prefix + '_DEREF', name)
