        # Transform xyz to grid coor.
        uc = self.unit_cell
        orth_to_grid = uc.orth_to_frac * self.unit_cell_shape.reshape(3, 1)
        # TODO origin shift is not taken into account
        grid_coor = xyz @ orth_to_grid.T
