def parse_volume(fid, fmt=None):
    try:
        fname = fid.name
    except AttributeError:
        fname = fid

    if fmt is None:
        fmt = os.path.splitext(fname)[-1][1:]
    if fmt in ('ccp4', 'map'):
        p = CCP4Parser(fname)
    elif fmt == 'mrc':
        p = MRCParser(fname)
    else:
        raise ValueError('Extension of file is not supported.')
    return p


